use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn determine_usage_type (symbol : & str , value : i32 , _pos : usize) -> String { let lower = symbol . to_lowercase () ; if lower . contains ("hash") || lower . contains ("sha") || lower . contains ("md5") { "crypto" . to_string () } else if lower . contains ("bit") || lower . contains ("mask") || (value > 0 && (value & (value - 1)) == 0) { "bitwise" . to_string () } else if lower . contains ("size") || lower . contains ("len") || lower . contains ("capacity") { "sizing" . to_string () } else if lower . contains ("index") || lower . contains ("offset") || lower . contains ("pos") { "indexing" . to_string () } else if lower . contains ("version") || lower . contains ("major") || lower . contains ("minor") { "versioning" . to_string () } else if lower . contains ("error") || lower . contains ("code") || value < 0 { "error_code" . to_string () } else if lower . contains ("test") || lower . contains ("mock") || lower . contains ("example") { "testing" . to_string () } else if lower . contains ("const") || lower . contains ("static") { "constant" . to_string () } else { "general" . to_string () } }